   137	function optionalPositiveInteger(command: string, field: string, value: unknown): number | undefined {
   138	  if (value === undefined) return undefined;
   139	  if (typeof value !== 'number' || !Number.isFinite(value) || !Number.isInteger(value) || value <= 0) {
   140	    throw new Error(`${command}: --${field} must be a finite positive integer`);
   141	  }
   142	  return value;
   143	}
   144	
   145	function optionalNonnegativeInteger(
   146	  command: string,
   147	  field: string,
   148	  value: unknown,
   149	  maximum?: number,
   150	): number | undefined {
   151	  if (value === undefined) return undefined;
   152	  if (typeof value !== 'number'
   153	    || !Number.isFinite(value)
   154	    || !Number.isInteger(value)
   155	    || value < 0
   156	    || (maximum !== undefined && value > maximum)) {
   157	    const maximumClause = maximum === undefined ? '' : ` <= ${maximum}`;
   158	    throw new Error(`${command}: --${field} must be a finite nonnegative integer${maximumClause}`);
   159	  }
   160	  return value;
   161	}
