   916	export function isStrictManagedReviewFindingProposal(value: unknown): value is ManagedReviewFinalEnvelopeFinding {
   917	  if (!isPlainRecord(value)) return false;
   918	  const allowed = new Set(['desc', 'severity', 'category', 'files', 'evidenceState', 'uncertaintyReason']);
   919	  if (Object.keys(value).some(key => !allowed.has(key))) return false;
   920	  if (typeof value.desc !== 'string' || value.desc.trim().length === 0) return false;
   921	  if (!['critical', 'high', 'medium', 'low'].includes(String(value.severity))) return false;
   922	  if (!['happy', 'edge', 'adversarial', 'missing'].includes(String(value.category))) return false;
   923	  if (value.files !== undefined
   924	    && (!isStringArray(value.files) || value.files.some(file => file.trim().length === 0))) return false;
   925	  if (value.evidenceState !== undefined
   926	    && value.evidenceState !== 'suspected'
   927	    && value.evidenceState !== 'verified') return false;
   928	  if (value.evidenceState === 'suspected') {
   929	    if (typeof value.uncertaintyReason !== 'string' || value.uncertaintyReason.trim().length === 0) return false;
