   950	      ? { kind: 'malformed' }
   951	      : { kind: 'ordinary' };
   952	  }
   953	  if (!isPlainRecord(parsed)) return { kind: 'ordinary' };
   954	  if (parsed.schemaVersion !== MANAGED_REVIEW_FINAL_PROPOSAL_SCHEMA_VERSION) {
   955	    return trimmed.includes(MANAGED_REVIEW_FINAL_PROPOSAL_SCHEMA_VERSION)
   956	      ? { kind: 'malformed' }
   957	      : { kind: 'ordinary' };
   958	  }
   959	
   960	  const conclusion = parsed.conclusion;
   961	  const allowed = new Set([
   962	    'schemaVersion', 'storyId', 'providerAgent', 'lane', 'reviewRunId', 'conclusion',
   963	    'readManifest', 'readLog', 'readDiagnostics', 'note', 'findings',
   964	  ]);
