   966	  const validReadManifest = isPlainRecord(readManifest)
   967	    && isStringArray(readManifest.filesReadFully)
   968	    && isStringArray(readManifest.filesTriagedByName)
   969	    && (readManifest.scanEscalationReason === null || typeof readManifest.scanEscalationReason === 'string')
   970	    && (readManifest.candidateSpecSetDigest === undefined || typeof readManifest.candidateSpecSetDigest === 'string')
   971	    && (readManifest.corpusDigest === undefined || typeof readManifest.corpusDigest === 'string');
   972	  const validConclusionPayload = conclusion === 'pass'
   973	    ? typeof parsed.note === 'string'
   974	      && parsed.note.trim().length > 0
   975	      && (parsed.findings === undefined || (Array.isArray(parsed.findings) && parsed.findings.length === 0))
   976	    : conclusion === 'findings'
   977	      && Array.isArray(parsed.findings)
   978	      && parsed.findings.length > 0
   979	      && parsed.findings.every(isStrictManagedReviewFindingProposal)
   980	      && (parsed.note === undefined || (typeof parsed.note === 'string' && parsed.note.trim().length > 0));
   981	  if (Object.keys(parsed).some(key => !allowed.has(key))
   982	    || typeof parsed.storyId !== 'string'
   983	    || typeof parsed.providerAgent !== 'string'
   984	    || typeof parsed.lane !== 'string'
   985	    || typeof parsed.reviewRunId !== 'string'
